# UARD (Untrapped Auto-Repair Diagnostic) ver 1.0.0 - TRUE BASELINE
# Canonical repair endpoint: 000-999 audit middleman.
$ErrorActionPreference='Stop'
$UARDName='UARD (Untrapped Auto-Repair Diagnostic)';$UARDVersion='1.0.0';$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$Middleman='https://untrapped-update-middleman-000-999-production.up.railway.app';$ArtifactBase=$Middleman+'/v1/artifact/';$Report=Join-Path $Root 'repair-success-latest.txt';$BackupRoot=Join-Path $Root 'repair-backups';$log=New-Object 'System.Collections.Generic.List[string]';$changed=$false;$failed=$false;$unknown=$false;$CanonicalCache=@{};$sw=[Diagnostics.Stopwatch]::StartNew()
function Log([string]$m){$x='['+(Get-Date -Format HH:mm:ss)+'] '+$m;Write-Host $x;[void]$log.Add($x)}
function HashBytes([byte[]]$b){$s=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($s.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function Normalize([byte[]]$b,[string]$n,[string]$t){if($t -eq 'json'){return $b};$s=[Text.Encoding]::UTF8.GetString($b).TrimStart([char]0xFEFF).Trim();if(-not $s.StartsWith('{')){return $b};try{$j=$s|ConvertFrom-Json -ErrorAction Stop}catch{return $b};foreach($k in @('powershell','script','source','code','content','text','body')){if($j.PSObject.Properties.Name -contains $k -and $j.$k -is [string]){try{return [Text.Encoding]::UTF8.GetBytes([string]$j.$k)}catch{return $b}}};return $b}
function RemoteBytes([string]$n,[string]$t){if($CanonicalCache.ContainsKey($n)){return $CanonicalCache[$n]};for($a=1;$a -le 4;$a++){try{Log ('FETCH '+$n+' attempt '+$a+'/4');$q=[Net.HttpWebRequest]::Create($ArtifactBase+$n+'?cb='+[DateTime]::UtcNow.Ticks);$q.Method='GET';$q.Timeout=30000;$q.ReadWriteTimeout=30000;$q.UserAgent='UARD/1.0';$r=$q.GetResponse();try{$st=$r.GetResponseStream();$ms=New-Object IO.MemoryStream;$st.CopyTo($ms);$raw=$ms.ToArray()}finally{if($st){$st.Dispose()};$r.Dispose()};$x=Normalize $raw $n $t;$CanonicalCache[$n]=$x;Log ('DOWNLOAD OK '+$n+' '+$x.Length+' bytes SHA256='+(HashBytes $x));return $x}catch{$c=0;try{$c=[int]$_.Exception.Response.StatusCode}catch{};if($c -in @(408,429) -or $c -ge 500){Log ('TRANSIENT FETCH ERROR '+$n+' HTTP '+$c+'; retrying')}else{Log ('CANONICAL FETCH ERROR '+$n+': '+$_.Exception.Message);break}}};$script:unknown=$true;Log ('UNVERIFIED '+$n+' canonical source unavailable.');return $null}
function ValidPS([byte[]]$b,[string]$n){try{$s=[Text.Encoding]::UTF8.GetString($b);$null=[scriptblock]::Create($s);return $true}catch{Log ('SCRIPT VALIDATION FAILED '+$n+': '+$_.Exception.Message);return $false}}
function Backup([string]$p){if(Test-Path -LiteralPath $p){$d=Join-Path $BackupRoot (Get-Date -Format 'yyyyMMdd-HHmmssfff');New-Item -ItemType Directory -Path $d -Force|Out-Null;Copy-Item -LiteralPath $p -Destination (Join-Path $d (Split-Path $p -Leaf)) -Force;Log ('BACKUP '+$p)}}
function Install([string]$p,[byte[]]$b){$d=Split-Path -Parent $p;if(-not(Test-Path $d)){New-Item -ItemType Directory -Path $d -Force|Out-Null};$tmp=$p+'.uaudtmp';[IO.File]::WriteAllBytes($tmp,$b);Move-Item -LiteralPath $tmp -Destination $p -Force}
Log ($UARDName+' ver '+$UARDVersion+' - TRUE BASELINE');Log ('MIDDLEMAN '+$Middleman);Log 'Protected boundary: no Windows Firewall/WFP/DNS/routes/Hosts/proxy/VPN/adapter/override-policy changes.'
$core=@('config.json','packet-filter.ps1','self-repair.ps1','status-untrapped.ps1','ultra-mode.ps1');foreach($n in $core){$p=Join-Path $Root $n;$t=if($n -eq 'config.json'){'json'}else{'ps1'};$x=RemoteBytes ('ultra-mode/'+$n) $t;if($null -eq $x){continue};if($t -eq 'ps1' -and -not(ValidPS $x $n)){$script:failed=$true;continue};$cur=if(Test-Path $p){[IO.File]::ReadAllBytes($p)}else{$null};if($null -eq $cur -or (HashBytes $cur) -ne (HashBytes $x)){Backup $p;Install $p $x;$script:changed=$true;Log ('REPAIRED '+$n)}else{Log ('CURRENT '+$n)}}
foreach($n in @('WinDivert.dll','WinDivert64.sys')){$f=Get-ChildItem -LiteralPath $Root -Filter $n -File -Recurse -ErrorAction SilentlyContinue|Select-Object -First 1;if($f){Log ('NATIVE OK '+$n)}else{Log ('NATIVE MISSING '+$n);$script:failed=$true}}
$diagnosis='NO REPAIR REQUIRED';if($failed){$diagnosis='REPAIR INCOMPLETE'}elseif($unknown){$diagnosis='VERIFICATION INCOMPLETE'}elseif($changed){$diagnosis='REPAIR SUCCESS'};Log ('[DIAGNOSIS] '+$diagnosis);$sw.Stop();Log ('RUNTIME '+$sw.Elapsed.ToString());if($changed -or $failed -or $unknown){$reportText=@($UARDName+' ver '+$UARDVersion+' - TRUE BASELINE','Run: '+(Get-Date),'Diagnosis: '+$diagnosis,'Middleman: '+$Middleman,'','Protected boundary unchanged.','',$log);$reportText|Set-Content -LiteralPath $Report -Encoding UTF8;Start-Process notepad.exe -ArgumentList @($Report)|Out-Null};if($failed){exit 1};if($unknown){exit 2};exit 0
